<?php require_once '../config.php';require_admin();$stats=['Customers'=>db()->query('SELECT COUNT(*) FROM customers')->fetchColumn(),'Codes generated'=>db()->query('SELECT COUNT(*) FROM product_codes')->fetchColumn(),'Codes redeemed'=>db()->query("SELECT COUNT(*) FROM product_codes WHERE status='redeemed'")->fetchColumn(),'Points issued'=>db()->query('SELECT COALESCE(SUM(points),0) FROM points_ledger WHERE points>0')->fetchColumn()];$recent=db()->query('SELECT c.code,u.name AS customer,c.redeemed_at FROM product_codes c LEFT JOIN customers u ON u.id=c.customer_id WHERE c.status="redeemed" ORDER BY c.redeemed_at DESC LIMIT 10')->fetchAll();page_start('Owner dashboard');?><div class="stats"><?php foreach($stats as $k=>$v):?><div class="stat"><span><?=e($k)?></span><strong><?=number_format((int)$v)?></strong></div><?php endforeach;?></div><div class="actions"><a class="btn" href="codes.php">Generate product codes</a><a class="btn secondary" href="customers.php">Manage customers</a><a class="btn secondary" href="rewards.php">Manage rewards</a></div><section class="panel"><h2>Recent redemptions</h2><div class="table-wrap"><table><tr><th>Code</th><th>Customer</th><th>Redeemed at</th></tr><?php foreach($recent as $r):?><tr><td><?=e($r['code'])?></td><td><?=e($r['customer']??'—')?></td><td><?=e($r['redeemed_at'])?></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="3">No codes redeemed yet.</td></tr><?php endif;?></table></div></section><?php page_end();?>
